#!/usr/bin/env bash
# ══════════════════════════════════════════════════════════════════════════
#  Escenario Killercoda — Misión CSI (MitM) · Módulo 4 · Clase 6 · CIBER13 UM
#  Genera la carpeta lab-csi-mitm/ en tu repo clonado. Funciona en macOS y Linux.
#     cd um-ciber13-modulo4 && bash crear-lab-csi.sh
#     git add -A && git commit -m "Clase 6: Mision CSI MitM" && git push
# ══════════════════════════════════════════════════════════════════════════
set -e
DEST="lab-csi-mitm"; SHA_ESPERADO="517a358fe4a9b7bf69a2738ee32a272166e007834d44d46c77e2062fb9c8c07c"
TMP=$(mktemp)
cat > "$TMP.b64" <<'B64EOF'

B64EOF
base64 -d < "$TMP.b64" > "$TMP.tgz"
if command -v sha256sum >/dev/null 2>&1; then SHA_REAL=$(sha256sum "$TMP.tgz" | cut -d' ' -f1); else SHA_REAL=$(shasum -a 256 "$TMP.tgz" | cut -d' ' -f1); fi
[ "$SHA_REAL" = "$SHA_ESPERADO" ] || { echo "ERROR: huella no coincide, archivo corrupto"; rm -f "$TMP".*; exit 1; }
rm -rf "$DEST"; mkdir -p "$DEST"; tar xzf "$TMP.tgz" -C "$DEST"
chmod +x "$DEST"/background.sh "$DEST"/foreground.sh "$DEST"/assets/ct-*
for f in "$DEST"/background.sh "$DEST"/foreground.sh "$DEST"/assets/ct-*; do git update-index --add --chmod=+x "$f" 2>/dev/null || true; done
rm -f "$TMP".*
echo "Escenario creado en $DEST/  ->  git add -A && git commit -m 'Clase 6: Mision CSI MitM' && git push"
echo "Se publica en: https://killercoda.com/cruzgio/scenario/lab-csi-mitm"
